/** Paid transactions / receipts — immutable once created. Source of truth for completed commerce. */
export const sales = sqliteTable('sales', {
  id: text('id').primaryKey(),
  saleNumber: text('sale_number').notNull().unique(), // SA-0001
  customerId: text('customer_id').references(() => customers.id), // nullable for anonymous/walk-in
  sourceType: text('source_type', { enum: ['direct_sale', 'repair', 'customer_order', 'backorder'] }).notNull(),
  sourceId: text('source_id'), // ID of source document (nullable for direct_sale)
